# Expected values generated by test/scipy/gen_stats_final_misc.py (scipy 1.18.1).
import numpy as np
import scipy.stats as st

def close(a, b, rtol: float = 1e-9) -> bool:
    return abs(a - b) <= 1e-12 + rtol * abs(b)

x = [2.1, 3.4, 1.9, 5.6, 4.4, 3.8, 2.7, 6.1, 4.9, 3.3]

@test
def test_misc():
    assert close(st.kstat(x, 1), 3.8199999999999994)
    assert close(st.kstat(x, 2), 2.024000000000001)
    assert close(st.kstat(x, 3), 0.7168000000000272)
    assert close(st.kstat(x, 4), -4.123292380950916)
    assert close(st.kstatvar(x, 1), 0.20240000000000008)
    assert close(st.kstatvar(x, 2), 0.40747171428583473)
    assert close(st.gstd(x), 1.4842321559575171)
    r = st.bayes_mvs(x, 0.9)
    assert close(r[0][0], 3.8199999999999994, 1e-8)
    assert close(r[0][1][0], 2.995302884671225, 1e-8)
    assert close(r[0][1][1], 4.644697115328774, 1e-8)
    assert close(r[1][0], 2.602285714285714, 1e-8)
    assert close(r[1][1][0], 1.0766608021885045, 1e-8)
    assert close(r[1][1][1], 5.4783103189962805, 1e-8)
    assert close(r[2][0], 1.5567486887748336, 1e-8)
    assert close(r[2][1][0], 1.0376226685016594, 1e-8)
    assert close(r[2][1][1], 2.3405790563440236, 1e-8)
    assert st.PermutationMethod(n_resamples=99).n_resamples == 99
    assert st.BootstrapMethod().method == 'BCa'
